import { describe, expect, it } from "vitest";
import indexHtml from "../index.html?raw";
import manifestText from "../public/site.webmanifest?raw";
import faviconSvg from "../public/favicon.svg?raw";

// The brand files in public/ (generated by scripts/generateBrandAssets.mjs) and the tags in
// index.html that point at them. Binary files are read through Vite's `?inline`, which hands back a
// base64 data URI: @types/node is not installed, so there is no fs to read them with.

const binaries = import.meta.glob("../public/*.{png,ico}", { query: "?inline", import: "default", eager: true }) as Record<
  string,
  string
>;
const publicFiles = Object.keys(import.meta.glob("../public/*")).map((path) => path.replace("../public/", ""));

function bytesOf(name: string): Uint8Array {
  const uri = binaries[`../public/${name}`];
  if (uri === undefined) throw new Error(`public/${name} is missing`);
  return Uint8Array.from(atob(uri.slice(uri.indexOf(",") + 1)), (c) => c.charCodeAt(0));
}

const PNG_SIGNATURE = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];

// A PNG's first chunk is IHDR: width and height are the two big-endian words at bytes 16 and 20.
function pngSize(bytes: Uint8Array): [number, number] {
  expect([...bytes.slice(0, 8)]).toEqual(PNG_SIGNATURE);
  expect(String.fromCharCode(...bytes.slice(12, 16))).toBe("IHDR");
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  return [view.getUint32(16), view.getUint32(20)];
}

describe("the raster brand files", () => {
  it.each([
    ["favicon-32x32.png", 32, 32],
    ["apple-touch-icon.png", 180, 180],
    ["icon-192.png", 192, 192],
    ["icon-512.png", 512, 512],
    ["og-image.png", 1200, 630],
  ])("%s is a %i x %i PNG", (name, width, height) => {
    expect(pngSize(bytesOf(name))).toEqual([width, height]);
  });

  it("favicon.ico holds 16, 32 and 48px entries, each a PNG of that size", () => {
    const bytes = bytesOf("favicon.ico");
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    expect(view.getUint16(0, true)).toBe(0); // reserved
    expect(view.getUint16(2, true)).toBe(1); // type: icon
    const count = view.getUint16(4, true);
    expect(count).toBe(3);
    const sizes: number[] = [];
    for (let i = 0; i < count; i++) {
      const entry = 6 + 16 * i;
      const size = view.getUint8(entry);
      const length = view.getUint32(entry + 8, true);
      const offset = view.getUint32(entry + 12, true);
      expect(offset + length).toBeLessThanOrEqual(bytes.length);
      expect(pngSize(bytes.slice(offset, offset + length))).toEqual([size, size]);
      sizes.push(size);
    }
    expect(sizes).toEqual([16, 32, 48]);
  });
});

describe("favicon.svg", () => {
  it("is the between mark: two ivory bars with a red dot between them, as plain shapes", () => {
    expect(faviconSvg).toContain('viewBox="0 0 64 64"');
    expect(faviconSvg.match(/<rect /g)?.length).toBe(3); // the ground and the two bars
    expect(faviconSvg.match(/fill="#f2eadf"/g)?.length).toBe(2);
    expect(faviconSvg.match(/<circle [^>]*fill="#e0414f"/g)?.length).toBe(1);
  });

  it("draws nothing it has to fetch or run: no text, script, image or external reference", () => {
    expect(faviconSvg).not.toMatch(/<text|<script|<image|<use|<style|href=|url\(|font-family/);
  });
});

describe("site.webmanifest", () => {
  const manifest = JSON.parse(manifestText) as {
    name: string;
    short_name: string;
    theme_color: string;
    background_color: string;
    icons: { src: string; sizes: string; type: string; purpose?: string }[];
  };

  it("names the app and paints it the canvas color", () => {
    expect(manifest.name).toBe("Between Jobs");
    expect(manifest.short_name).toBe("Between Jobs");
    expect(manifest.theme_color).toBe("#070607");
    expect(manifest.background_color).toBe("#070607");
  });

  it("lists a 192 and a 512 PNG that exist at those sizes, and are safe to mask", () => {
    expect(manifest.icons.map((icon) => icon.sizes)).toEqual(["192x192", "512x512"]);
    for (const icon of manifest.icons) {
      const size = Number.parseInt(icon.sizes, 10);
      expect(icon.type).toBe("image/png");
      expect(icon.purpose).toContain("maskable");
      expect(pngSize(bytesOf(icon.src))).toEqual([size, size]);
    }
  });
});

describe("index.html", () => {
  const tag = (pattern: RegExp): string => {
    const match = pattern.exec(indexHtml);
    if (match === null) throw new Error(`index.html has nothing matching ${String(pattern)}`);
    return match[0];
  };
  const metaContent = (attribute: "name" | "property", key: string): string => {
    const match = new RegExp(`<meta\\s+${attribute}="${key}"\\s+content="([^"]*)"`, "s").exec(indexHtml);
    if (match === null) throw new Error(`index.html has no <meta ${attribute}="${key}">`);
    return match[1];
  };

  it("has a title and a one-sentence description with no superlatives", () => {
    expect(tag(/<title>[^<]+<\/title>/)).toBe("<title>Between Jobs</title>");
    const description = metaContent("name", "description");
    expect(description.length).toBeGreaterThan(40);
    expect(description.length).toBeLessThanOrEqual(200);
    expect(description.match(/[.!?](\s|$)/g)?.length ?? 0).toBeLessThanOrEqual(1);
    expect(description).not.toMatch(/\b(best|leading|revolutionary|powerful|ultimate|#1|world-class|magic)\b/i);
  });

  it("is dark: a theme color and color scheme that match the canvas", () => {
    expect(metaContent("name", "theme-color")).toBe("#070607");
    expect(metaContent("name", "color-scheme")).toBe("dark");
  });

  it("links the SVG icon, PNG and ICO fallbacks, the touch icon and the manifest, all of which exist", () => {
    const links = [...indexHtml.matchAll(/<link\s+rel="([^"]+)"\s+href="(\/[^"]+)"/g)].map((m) => [m[1], m[2]] as const);
    expect(links.map(([rel, href]) => `${rel} ${href}`)).toEqual([
      "icon /favicon.svg",
      "icon /favicon-32x32.png",
      "icon /favicon.ico",
      "apple-touch-icon /apple-touch-icon.png",
      "manifest /site.webmanifest",
    ]);
    for (const [, href] of links) expect(publicFiles, href).toContain(href.slice(1));
  });

  it("carries Open Graph and Twitter card tags that use the absolute og-image URL", () => {
    const image = "https://between-jobs.tech/og-image.png";
    expect(metaContent("property", "og:image")).toBe(image);
    expect(metaContent("name", "twitter:image")).toBe(image);
    expect(metaContent("name", "twitter:card")).toBe("summary_large_image");
    expect(metaContent("property", "og:type")).toBe("website");
    expect(metaContent("property", "og:title")).toBe("Between Jobs");
    expect(metaContent("property", "og:image:width")).toBe("1200");
    expect(metaContent("property", "og:image:height")).toBe("630");
    expect(metaContent("property", "og:description")).toBe(metaContent("name", "description"));
    expect(metaContent("name", "twitter:description")).toBe(metaContent("name", "description"));
  });

  it("keeps the inline style that paints the page before any script runs, and adds no inline script", () => {
    expect(indexHtml).toMatch(/<style>\s*html\s*\{\s*background:\s*#070607;\s*\}\s*<\/style>/);
    expect(indexHtml).not.toMatch(/<script(?![^>]*\ssrc=)[^>]*>/);
  });
});
